# Col 1 is all 5s, col 7 is all 5s
# Fill all 0s that are horizontally adjacent to at least one 5 in cols 1 or 7

test = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

# Fill 0s that are adjacent (horizontal) to a 5
result = []
for r in range(5):
    row = []
    for c in range(12):
        if test[r][c] == 5:
            row.append(5)
        elif test[r][c] == 0:
            # Check if this 0 is horizontally adjacent to a 5
            left_is_5 = test[r][c-1] == 5 if c > 0 else False
            right_is_5 = test[r][c+1] == 5 if c < 11 else False
            # Also check if vertically adjacent to all-5-wall at col 1 or col 7
            if c in [2,3,4,5,6,8,9]:
                if c >= 2: left_is_5 = left_is_5 or (test[r-1][c-1] == 0 and r > 0 and test[r-1][0] == 5)
            if left_is_5 or right_is_5:
                row.append(7)
            else:
                row.append(0)
    result.append(row)

print("Horizontal adjacency fill:")
for row in result:
    print(row)

# Simpler: fill 0s adjacent to ANY 5 (horizontally or vertically)
result2 = []
for r in range(5):
    for c in range(12):
        if test[r][c] == 0:
            orth_5 = (test[r][c-1] == 5 if c > 0 else False) or (test[r][c+1] == 5 if c < 11 else False) or \
                     (test[r-1][c] == 5 if r > 0 else False) or (test[r+1][c] == 5 if r < 4 else False)
            output[r][c] = 7 if orth_5 else 0
    else:
        result2.append(list(test[r]))

# Last chance - try a different interpretation: pairs of 7/8 at symmetric positions

test = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

# Try: fill all 0s at positions where both horizontal neighbors are 5 OR both vertical neighbors are 5
output = [row[:] for row in test]

for r in range(5):
    for c in range(12):
        if test[r][c] == 0:
            # Check all 4 orthogonal neighbors
            row_env = [test[r][c-1] if c > 0 else 6, test[r][c+1] if c < 11 else 6]
            col_env = [test[r-1][c] if r > 0 else 6, test[r+1][c] if r < 4 else 6]

            # https://arc-site.mila.cs.cmu.edu if both orthogonal are 5s
            if all(env == 5 for env in row_env):
                output[r][c] = 7  # edge
            elif all(env == 5 for env in col_env):
                output[r][c] = 7  # vertical edge
            elif row_env[0] == 5 and col_env[0] == 5 and row_env[1] == 5 and col_env[1] == 5:
                output[r][c] = 8  # interior corner
            else:
                output[r][c] = 0

print("Edge/interior based on orthogonal 5s:")
for row in output:
    print(row)
